// Two propositional predicates over compound IRIs. The
// PopulationLevel scope marker rides via the multi-class data
// header (D52 §12 #8 / ESL §4.5a) — the inductive-type resource
// the compiler emits will have core:is_a = [InductiveType,
// PopulationLevel]. The statistics institution reads this marker
// at MeasurementClaim admissibility time (§7.4 epistemic-scope
// check) and admits population-level claims only from biological-
// or nested-replication SampleSets.

namespace core   = "urn:eigenius:core";
namespace stats  = "urn:eigenius:measurements";
namespace screen = "urn:eigenius:demo:screen";

data screen:HasLowIC50      : core:string -> Prop, stats:PopulationLevel { }
data screen:StrongInhibitor : core:string -> Prop, stats:PopulationLevel { }

// Six raw IC50 reads of EIG_0291 against CDK2 on a Kinase-Glo
// plate. Tightly clustered (mean ≈ 85, SD ≈ 4.5) so the one-sample
// t-test against threshold 100 nM rejects H0 cleanly under any
// reasonable α.
//
// The SingleSampleEstimate macro lands the Bundle at the
// (CompleteRandom, Unblocked, NoFactor, BiologicalReplication,
// CrossSectional) product position — D52 §5.4 dispatch table.
// BiologicalReplication is what admits the PopulationLevel-marked
// HasLowIC50 predicate downstream.

namespace reflection = "urn:eigenius:reflection";
namespace stats      = "urn:eigenius:measurements";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:m_eig0291_sampleset : stats:SampleSetResource {
    reflection:source      = "instrument-log:kinase-glo-plate-2026-03-11-confirmatory";
    reflection:observed_at = "2026-03-11T10:18:42Z";

    stats:sample_set_value = stats:SingleSampleEstimate(
        [78.0, 82.0, 85.0, 88.0, 91.0, 86.0],
        BiologicalReplication(),
    );
}

resource screen:m_eig0291_sampleset_trace : reflection:ObservationTrace {
    reflection:resource  = screen:m_eig0291_sampleset;
    reflection:source    = "instrument-log:kinase-glo-plate-2026-03-11-confirmatory";
    reflection:timestamp = "2026-03-11T10:18:42Z";
}

// The MeasurementClaim. Its commit triggers D52's AutoOnLoad gate
// which recomputes the claim from the SampleSet's raw reads, runs
// the §7.4 epistemic-scope check (BiologicalReplication admits
// PopulationLevel ✓), and emits Verdict::Holds at the verdict-IRI
// derived from the runtime-invocation IRI.
//
// The canonical_proposition slot carries HasLowIC50(EIG_0291) — the
// proposition the D49 witness index hashes to compute the
// IsDerivedAs witness key. Once the trace below pairs the claim
// with the validate_measurement_claim procedure, IsDerivedAs(claim_iri,
// HasLowIC50(EIG_0291)) is admitted; any downstream DerivedEvidence
// citation of this claim consumes that witness.

namespace reflection = "urn:eigenius:reflection";
namespace stats      = "urn:eigenius:measurements";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:claim_eig0291_lowic50 : stats:MeasurementClaim {
    stats:sample_set = screen:m_eig0291_sampleset;

    stats:null_hypothesis = type_expr(
        screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
    );
    stats:alternative_hypothesis = type_expr(
        screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
    );
    reflection:canonical_proposition = type_expr(
        screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
    );

    stats:alpha = 0.05;
    stats:effect_size = Absolute(100.0, "nM");
    stats:directionality = TwoSided();
    stats:variance_assumption = WelchUnequal();
    stats:outlier_exclusion = Identity();
}

resource screen:claim_eig0291_lowic50_trace : reflection:ProgramTrace {
    reflection:resource  = screen:claim_eig0291_lowic50;
    reflection:source    = "statistics-institution:validate_measurement_claim";
    reflection:timestamp = "2026-03-11T10:18:42Z";
}

// D52's AutoOnLoad gate fired on the MeasurementClaim commit and
// emitted a Verdict resource. Find it by querying for a Verdict
// whose verdict_subject points back at the claim IRI.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:verdict_query_class": ?qc,
    "urn:eigenius:core:ctor_name":                  ?ctor
}
WHERE ?subject = "urn:eigenius:demo:screen:claim_eig0291_lowic50"
RETURN [] {
    verdict_iri:    ?v,
    ctor:           ?ctor,
    query_class:    ?qc,
    claim:          ?subject
}

// The literature rule, specialized to EIG_0291. Universal rules
// (forall (c : core:string), HasLowIC50(c) -> StrongInhibitor(c))
// are admissible via the JustifiedBy.spec_str constructor — the
// drug-screening fixture in crates/eigenius-reasoning/tests/
// fixtures/drug_screening.esl uses the specialized form for
// brevity; the d39_composition.esl fixture in the statistics crate
// uses the universal form with SpecStr.

namespace reflection = "urn:eigenius:reflection";
namespace screen     = "urn:eigenius:demo:screen";

resource screen:rule_strong : reflection:DeclaredResource {
    reflection:declared_by = "literature:smith_et_al_2024_3.2";
    reflection:rationale   = "IC50 < 100 nM at a kinase target is the standard strong-inhibitor threshold.";

    reflection:canonical_proposition = type_expr(
        screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
        ->
        screen:StrongInhibitor("urn:eigenius:demo:screen:EIG_0291")
    );
}

resource screen:rule_strong_trace : reflection:DeclarationTrace {
    reflection:resource    = screen:rule_strong;
    reflection:declared_by = "literature:smith_et_al_2024_3.2";
    reflection:timestamp   = "2026-04-10T09:00:00Z";
}

// The reasoning sentence. Three slots:
//
// - proposition: StrongInhibitor(EIG_0291) — the conclusion.
// - justification: App(DeclaredEvidence(rule), DerivedEvidence(claim))
//   — the JustificationTerm carrying the agent's structural
//   warrant. App is Artemov Application: applying the rule to the
//   measurement claim.
// - certificate: the kernel-checkable JustifiedBy term that
//   inhabits JustifiedBy(justification, proposition). The kernel's
//   NbE checker type-checks this against the expected indexed type;
//   the two grounding constructors (declared, derived) synthesize
//   their ChainWitness arguments from the witness index.
//
// At commit, D39's validate_justification AutoOnLoad gate runs.
// Both witnesses are admitted (rule_strong via DeclarationTrace,
// claim_eig0291_lowic50 via ProgramTrace) so the certificate
// type-checks and Verdict::Holds is committed alongside the
// sentence.

namespace reasoning = "urn:eigenius:reasoning";
namespace screen    = "urn:eigenius:demo:screen";

resource screen:concl_eig0291_strong : reasoning:ReasoningSentence {
    reasoning:subject_iri = "urn:eigenius:demo:screen:EIG_0291";

    reasoning:proposition = type_expr(
        screen:StrongInhibitor("urn:eigenius:demo:screen:EIG_0291")
    );

    reasoning:justification = App(
        DeclaredEvidence("urn:eigenius:demo:screen:rule_strong"),
        DerivedEvidence("urn:eigenius:demo:screen:claim_eig0291_lowic50")
    );

    reasoning:certificate = type_expr(
        app(
            // A : Prop
            screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291"),
            // B : Prop
            screen:StrongInhibitor("urn:eigenius:demo:screen:EIG_0291"),
            // j1
            DeclaredEvidence("urn:eigenius:demo:screen:rule_strong"),
            // j2
            DerivedEvidence("urn:eigenius:demo:screen:claim_eig0291_lowic50"),
            // c1 : JustifiedBy(DeclaredEvidence(rule), HasLowIC50 -> StrongInhibitor)
            //      — consumes IsDeclaredAs(rule_iri, ...) admitted by rule_strong_trace
            declared(
                "urn:eigenius:demo:screen:rule_strong",
                screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
                ->
                screen:StrongInhibitor("urn:eigenius:demo:screen:EIG_0291"),
                screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
            ),
            // c2 : JustifiedBy(DerivedEvidence(claim), HasLowIC50)
            //      — consumes IsDerivedAs(claim_iri, ...) admitted by
            //        claim_eig0291_lowic50_trace
            derived(
                "urn:eigenius:demo:screen:claim_eig0291_lowic50",
                screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291"),
                screen:HasLowIC50("urn:eigenius:demo:screen:EIG_0291")
            )
        )
    );
}

// D39's AutoOnLoad gate fired on the ReasoningSentence commit and
// emitted a Verdict resource. Find it by subject IRI.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:verdict_query_class": ?qc,
    "urn:eigenius:core:ctor_name":                  ?ctor
}
WHERE ?subject = "urn:eigenius:demo:screen:concl_eig0291_strong"
RETURN [] {
    verdict_iri: ?v,
    ctor:        ?ctor,
    query_class: ?qc,
    sentence:    ?subject
}

// Closure query — both verdicts in one result, with their query
// classes naming which institution fired. Walk the audit chain
// from a single result: each row carries the subject (claim or
// sentence), the institution that endorsed it, and the Holds/Fails
// verdict ctor.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:institution:verdict_subject":     ?subject,
    "urn:eigenius:institution:verdict_query_class": ?qc,
    "urn:eigenius:core:ctor_name":                  ?ctor
}
WHERE ?subject = "urn:eigenius:demo:screen:claim_eig0291_lowic50"
   OR ?subject = "urn:eigenius:demo:screen:concl_eig0291_strong"
RETURN [] {
    subject:     ?subject,
    institution: ?qc,
    verdict:     ?ctor
}
